    "explanation": "📘 **NCERT Fundamental Concept**: Work done by a force is defined as $W = \\vec{F} \\cdot \\vec{s} = F s \\cos\\theta$.\n\n⚡ **Step-by-Step Derivation & Calculations**:\n- When a person walks along a level horizontal road carrying a load on his head, the force applied on the load by the person is vertically upwards (to balance gravity).\n- The displacement $\\vec{s}$ of the load is along the horizontal direction.\n- The angle between force and displacement is $\\theta = 90^\\circ$.\n- Therefore, $W = F s \\cos 90^\\circ = 0$.\n\n✓ **Examiner Pro-Tip**: When $\\vec{F} \\perp \\vec{s}$, work done by the force is identically zero.",
