    "explanation": "📘 **NCERT Fundamental Concept**: Work done in a closed path (round trip) is zero only for conservative forces (like gravity, electrostatic force). For non-conservative forces like friction, the work done in a round trip is non-zero (always negative).\n\n⚡ **Step-by-Step Derivation & Calculations**:\n- In the presence of friction or viscous drag, $\\oint \\vec{F}_{nc} \\cdot d\\vec{r} \\neq 0$. Thus, Assertion is false.\n- A force is always required to move a body against resistive forces or to accelerate/decelerate it during a round trip. Thus, Reason is false.\n\n✓ **Examiner Pro-Tip**: $\\oint \\vec{F}\\cdot d\\vec{r} = 0$ is the defining condition of conservative forces only.",
