    "explanation": "📘 **NCERT Fundamental Concept**: First Law of Thermodynamics and conservation of mechanical energy.\n\n⚡ **Step-by-Step Derivation & Calculations**:\n- At the top of a waterfall of height $h$, water of mass $m$ has gravitational potential energy $U = mgh$.\n- As it falls, this potential energy converts into kinetic energy $\\frac{1}{2}mv^2$.\n- When the water strikes the bottom and comes to rest, this kinetic energy is dissipated into internal thermal energy: $mgh = m c \\Delta T \\implies \\Delta T = \\frac{gh}{c}$.\n- Therefore, the temperature of water at the bottom is higher than at the top.\n\n✓ **Examiner Pro-Tip**: Joule demonstrated the mechanical equivalent of heat using the temperature rise of falling water.",
