    "explanation": "📘 **NCERT Fundamental Concept**: Total mechanical energy $E = K + U$.\n\n⚡ **Step-by-Step Derivation & Calculations**:\n- When only conservative forces do work, total mechanical energy is conserved: $\\Delta E = \\Delta K + \\Delta U = 0 \\implies \\Delta U = -\\Delta K$.\n- Thus, any increase in kinetic energy comes at the expense of an equal decrease in potential energy. (Assertion is true).\n- Total mechanical energy IS a conserved quantity in conservative force fields. Hence Reason is false.\n\n✓ **Examiner Pro-Tip**: $\\Delta K = -\\Delta U$ is the fundamental statement of mechanical energy conservation.",
