    "explanation": "📘 **NCERT Fundamental Concept**: Work done $W = F s \\cos\\theta$.\n\n⚡ **Step-by-Step Derivation & Calculations**:\n- When a force retards motion (opposes displacement), the angle $\\theta$ between $\\vec{F}$ and $\\vec{s}$ satisfies $90^\\circ < \\theta \\le 180^\\circ$.\n- Since $\\cos\\theta < 0$, the work done is **negative**, not zero. (Assertion is false).\n- Work done $W = F s \\cos\\theta$ depends directly on the angle $\\theta$. (Reason is true).\n\n✓ **Examiner Pro-Tip**: Retarding forces always do negative work, extracting kinetic energy from the moving body.",
