    "correctAnswer": 3,
    "explanation": "📘 **NCERT Fundamental Concept**: In an elastic collision, total linear momentum and total kinetic energy of the *system* are conserved, but energy and momentum are transferred between individual bodies.\n\n⚡ **Step-by-Step Derivation & Calculations**:\n- During collision, individual bodies experience forces and exchange momentum and kinetic energy; their individual values change. (Assertion is false).\n- When colliding bodies stick together and move with a common velocity, maximum kinetic energy is lost and the collision is defined as **perfectly inelastic** ($e = 0$). (Reason is false).\n\n✓ **Examiner Pro-Tip**: Perfectly elastic means $e = 1$ (no kinetic energy loss); sticking together means $e = 0$ (perfectly inelastic).",
